/** A stale proposal must be observed again after a human changes the page. */
export class BrowserControlChanged extends Error {
  constructor() {
    super("Browser control changed; observe the current page before acting");
    this.name = "BrowserControlChanged";
  }
}

/**
 * Cooperative control over one already-owned browser. This does not launch a
 * browser, authenticate a viewer, cancel native input, or decide test results.
 * The owner supplies settlement/input-release and fresh-observation callbacks.
 */
export function createBrowserHandoff({
  releaseAgentInput,
  releaseHumanInput,
  observe,
  signal,
  onChange,
  now = () => performance.now(),
}) {
  const lifetime = new AbortController();
  const agentActions = new Set();
  const humanActions = new Set();
  const requests = new Map();
  const waiters = new Set();
  let humanInput = Promise.resolve();
  const started = now();
  let state = "agent";
  let generation = 0;
  let pausedAt;
  let pausedMs = 0;
  let ended;

  const status = () => {
    const time = ended ?? now();
    const humanMs = pausedMs + (pausedAt === undefined ? 0 : time - pausedAt);
    return {
      state,
      generation,
      wallMs: time - started,
      activeMs: time - started - humanMs,
      humanMs,
      clockPaused: pausedAt !== undefined,
    };
  };
  const changed = () => {
    if (state === "agent" || state === "stopped") {
      for (const ready of waiters) ready();
      waiters.clear();
    }
    try {
      onChange?.(status());
    } catch {
      // Optional presentation cannot change input ownership.
    }
  };
  const check = () => lifetime.signal.throwIfAborted();
  const stop = (reason = new Error("Browser Run stopped")) => {
    if (state === "stopped") return;
    ended = now();
    state = "stopped";
    generation++;
    lifetime.abort(reason);
    changed();
  };
  const externalStop = () => stop(signal.reason);
  if (signal?.aborted) externalStop();
  else signal?.addEventListener("abort", externalStop, { once: true });

  // Stop releases the acknowledgment wait even if a native operation still
  // needs the owner's independent browser-close/cleanup path to settle it.
  const interruptible = (work) => {
    check();
    return new Promise((resolve, reject) => {
      const aborted = () => reject(lifetime.signal.reason);
      lifetime.signal.addEventListener("abort", aborted, { once: true });
      Promise.resolve(work)
        .then(resolve, reject)
        .finally(() => {
          lifetime.signal.removeEventListener("abort", aborted);
        });
    });
  };
  const run = async (owner, expectedGeneration, action) => {
    check();
    if (state !== owner || generation !== expectedGeneration)
      throw new BrowserControlChanged();
    const pending = owner === "agent" ? agentActions : humanActions;
    const task = Promise.resolve().then(action);
    pending.add(task);
    try {
      return await task;
    } finally {
      pending.delete(task);
    }
  };
  const settle = async (pending, releaseInput) => {
    await interruptible(Promise.allSettled([...pending]));
    check();
    await interruptible(Promise.resolve().then(releaseInput));
    check();
  };
  const pauseClock = () => {
    if (pausedAt === undefined) pausedAt = now();
  };
  const resumeClock = () => {
    if (pausedAt !== undefined) pausedMs += now() - pausedAt;
    pausedAt = undefined;
  };
  const request = (kind, id, expectedGeneration, operation) => {
    const prior = requests.get(id);
    if (prior) {
      if (prior.kind !== kind || prior.generation !== expectedGeneration)
        return Promise.reject(new BrowserControlChanged());
      return prior.reply;
    }
    check();
    if (generation !== expectedGeneration)
      return Promise.reject(new BrowserControlChanged());
    const entry = { kind, generation: expectedGeneration };
    // Save pairing before running callbacks, including reentrant observers.
    let resolve, reject;
    entry.reply = new Promise((accept, refuse) => {
      resolve = accept;
      reject = refuse;
    });
    requests.set(id, entry);
    // Admission closes synchronously with the request, before another input
    // can enter. The first await is settlement of already-admitted work.
    try {
      Promise.resolve(operation())
        .then((value) =>
          Object.freeze({ requestId: id, transition: kind, ...value }),
        )
        .then(resolve, reject);
    } catch (error) {
      reject(error);
    }
    return entry.reply;
  };

  return {
    status,
    async ready() {
      check();
      if (state !== "agent")
        await new Promise((resolve) => waiters.add(resolve));
      check();
      return status();
    },
    agent: (expectedGeneration, action) =>
      run("agent", expectedGeneration, action),
    human(expectedGeneration, action) {
      return run("human", expectedGeneration, () => {
        // Pointer commands may await native movement before pressing. Keep
        // later keys from reaching the page ahead of the click.
        const task = humanInput.then(() => {
          check();
          const admitted =
            (state === "human" && generation === expectedGeneration) ||
            (state === "resuming" && generation === expectedGeneration + 1);
          if (!admitted) throw new BrowserControlChanged();
          return action();
        });
        humanInput = task.catch(() => {});
        return task;
      });
    },
    takeOver(id, expectedGeneration) {
      return request("takeover", id, expectedGeneration, async () => {
        check();
        if (
          generation !== expectedGeneration ||
          (state !== "agent" && state !== "paused")
        )
          throw new BrowserControlChanged();
        const prior = state;
        state = "pausing";
        generation++;
        changed();
        try {
          await settle(
            prior === "agent" ? agentActions : humanActions,
            prior === "agent" ? releaseAgentInput : releaseHumanInput,
          );
          pauseClock();
          state = "human";
          changed();
          return status();
        } catch (error) {
          if (state !== "stopped") {
            // A failed takeover never admitted human input. Keep the original
            // agent owner able to settle its dialog/input instead of deadlocking
            // it behind a human lease that was never granted.
            if (prior === "agent") state = "agent";
            else {
              pauseClock();
              state = "paused";
            }
            changed();
          }
          throw error;
        }
      });
    },
    resume(id, expectedGeneration) {
      return request("resume", id, expectedGeneration, async () => {
        check();
        if (
          generation !== expectedGeneration ||
          (state !== "human" && state !== "paused")
        )
          throw new BrowserControlChanged();
        state = "resuming";
        generation++;
        changed();
        try {
          await settle(humanActions, releaseHumanInput);
          const observation = await interruptible(
            Promise.resolve().then(observe),
          );
          check();
          resumeClock();
          state = "agent";
          changed();
          return { ...status(), observation };
        } catch (error) {
          if (state !== "stopped") {
            state = "paused";
            changed();
          }
          throw error;
        }
      });
    },
    disconnect() {
      if (state !== "human") return;
      state = "paused";
      generation++;
      changed();
    },
    stop,
    close() {
      signal?.removeEventListener("abort", externalStop);
      stop();
    },
  };
}
